  const limit=String(v.creditLimit??'').trim();v.creditLimit=limit===''?null:Number(limit);if(v.creditLimit!=null&&!(v.creditLimit>0))throw Error('מסגרת האשראי צריכה להיות סכום חיובי, או ריקה.');
  if(entity?.kind==='credit'&&entity.statementsThrough){v.statementsThrough=entity.statementsThrough;if(entity.createdAt)v.createdAt=entity.createdAt;}
  else{v.statementsThrough=today();v.createdAt=today();}   // the owed amount typed now is charged on the first billing date after today
