// Applies a new or edited transaction to `next` (edit = undo the stored row + apply the new one, §B.1).
function saveTransactionInto(next,v,entity){
  v.amount=+v.amount;v.fx=+v.fx||next.fx;
  if(!(v.amount>0))throw Error('יש להזין סכום חיובי.');
  if(v.type==='transfer'){
    const from=next.accounts.find(a=>a.id===v.accountId),to=next.accounts.find(a=>a.id===v.toAccountId),cross=!!from&&!!to&&from.currency!==to.currency;
    const t={...makeTransfer(next,{fromId:v.accountId,toId:v.toAccountId,amount:v.amount,date:v.date,fx:v.fx,toAmount:cross?v.toAmount:'',description:v.description,goalId:entity?.type==='transfer'?entity.goalId:undefined}),id:v.id};
    if(entity?.type==='transfer'){t.tags=[...entity.tags||[]];if(entity.auto)t.auto={...entity.auto,confirm:false};}
    const problem=transferProblem(next,{...t,editing:entity||null});if(problem)throw Error(problem);
    if(entity)applyTransaction(next,entity,-1);applyTransaction(next,t);
    const closed=to.kind==='debt'&&Math.abs(next.accounts.find(a=>a.id===to.id).balance)<.005;
    return {v:t,message:closed?'כל הכבוד — ההלוואה נסגרה!':entity?'השינויים נשמרו':`העברה של ${money(t.amount,t.currency)} נרשמה: מ־${from.name} ל־${to.name}`};
  }
  v.currency=next.accounts.find(a=>a.id===v.accountId)?.currency||'ILS';
  v.tags=String(v.tags||'').split(',').map(s=>s.trim()).filter(Boolean);
  delete v.toAccountId;delete v.toAmount;delete v.goalId;if(v.type!=='expense')delete v.installment;
  if(v.type==='refund'){v.recurring=false;if(INCOME_LIKE.test(v.category))throw Error('החזר מקטין הוצאה, ולכן צריך לבחור לו קטגוריית הוצאה.');}
  if(v.type==='expense'&&!entity&&v.planOn){   // a plan replaces the single row; its due payments are recorded now (§B.5)
    const plan=createInstallmentPlan(next,{accountId:v.accountId,total:v.amount,count:Number(v.installments),purchaseDate:v.date,description:String(v.description||'').trim()||v.category,category:v.category,subcategory:v.subcategory||'',tags:v.tags,alreadyCharged:dialogState?.chargedTouched?String(v.alreadyCharged??'').trim():'',fx:v.fx},today());
    next.installments=[...(next.installments||[]),plan];materializeInstallments(next,today());
    const p=previewPlan(next,plan);
    return {v:null,skip:true,message:`נוספה עסקה בתשלומים: ${plan.description} · ${plan.count} × ${money(p.each,plan.currency)}`};
  }
  if(entity)applyTransaction(next,entity,-1);applyTransaction(next,v);
  return {v,message:entity?'השינויים נשמרו':undefined};
}
// The amount credited to the TO account follows the amount and rate until the user types it (cross-currency only).
function updateTransferAmount(el){
  if(el.name==='toAmount'){el.dataset.touched='1';return;}
  if(el.name!=='amount'&&el.name!=='fx')return;
  const box=document.querySelector('#entity-form [name=toAmount]');if(!box||box.dataset.touched)return;
  captureEntity();const v=dialogState.v,t=makeTransfer(data,{fromId:v.accountId,toId:v.toAccountId,amount:+v.amount,fx:+v.fx||data.fx});
  box.value=Number.isFinite(t.toAmount)&&t.toAmount>0?t.toAmount:'';dialogState.v.toAmount=box.value;
}
// transfer-new:<from>:<to> (accounts page, palette): a loan payment is prefilled with the monthly payment.
function openTransfer(fromId='',toId=''){
  const to=data.accounts.find(a=>a.id===toId),prefill={type:'transfer',accountId:fromId||'',toAccountId:toId||'',toAmount:''};
  if(to?.kind==='debt'&&to.payment>0)prefill.amount=Math.min(to.payment,Math.max(0,to.balance))||'';
  openEntity('transaction',null,prefill);
}
// A new deposit account takes its defaults from the after-discharge profile (MODULES), never over typed values.
function depositPrefill(v,entity){
  if(entity||v.kind!=='deposit'||v.releaseDate||dialogState.depositFilled)return;
  dialogState.depositFilled=true;const defaults=moduleHook('depositDefaults',{},data);
  if(defaults&&typeof defaults==='object')for(const [k,x] of Object.entries(defaults))if(x!=null&&x!==''&&(v[k]===''||v[k]==null||(k==='balance'&&!Number(v[k]))))v[k]=x;
}
// An account is in use when rows, plans or a card point at it; deleting it would break history (bills too).
function accountInUse(d,id,withBills=false){return d.transactions.some(t=>t.accountId===id||t.toAccountId===id)||(d.installments||[]).some(p=>p.accountId===id)||d.accounts.some(a=>a.kind==='credit'&&a.payFrom===id)||(withBills&&(d.bills||[]).some(b=>b.accountId===id));}
// One imported transfer row: resolve the TO account, fill a missing credited amount, apply the transfer rules.
function importTransferRow(next,t,row){
  const to=next.accounts.find(a=>a.id===row.toAccountId||a.name===row.toAccountName);
  if(!to)throw Error('לא נמצא חשבון יעד להעברה '+(row.description||'')+'. יש ליצור חשבון בשם '+(row.toAccountName||row.toAccountId||'')+'. לא נשמרו שינויים.');
  t.toAccountId=to.id;delete t.toAccountName;t.category='העברה';
  if(!(Number(t.toAmount)>0))t.toAmount=makeTransfer(next,{fromId:t.accountId,toId:to.id,amount:t.amount,fx:t.fx}).toAmount;
  const problem=transferProblem(next,t);if(problem)throw Error(problem+' לא נשמרו שינויים.');
}
