function captureEntity(){if(!dialogState)return;const form=document.querySelector('#entity-form');if(!form)return;for(const [key,value] of new FormData(form))dialogState.v[key]=value;if(dialogState.kind==='transaction'){dialogState.v.recurring=!!form.querySelector('[name=recurring]')?.checked;dialogState.v.planOn=!!form.querySelector('[name=planOn]')?.checked;}}
function saveEntity(){captureEntity();const {kind,entity}=dialogState,next=structuredClone(data),keys={transaction:'transactions',budget:'budgets',goal:'goals',account:'accounts',asset:'assets'};let v={...dialogState.v,id:entity?.id||uid()},message,skip=false;if(kind==='transaction')({v,message,skip=false}=saveTransactionInto(next,v,entity));
if(kind==='budget'){v.limit=+v.limit;if(!(v.limit>0))throw Error('יש להזין תקציב חיובי.');if(next.budgets.some(b=>b.category===v.category&&b.id!==v.id))throw Error('כבר קיים תקציב לקטגוריה הזו. אפשר לערוך אותו.');}
if(kind==='goal'){const rawTarget=String(v.target??'').trim();v.target=rawTarget===''?null:Number(rawTarget);for(const k of ['saved','monthly'])v[k]=+v[k];const rawAllocation=String(v.allocation??'').trim();v.allocation=v.accountId&&rawAllocation!==''?Number(rawAllocation):null;if(v.allocation!=null){if(!(v.allocation>=0))throw Error('הסכום המוקצה צריך להיות חיובי.');const info=accountAllocations({...next,goals:next.goals.filter(g=>g.id!==v.id)},v.accountId),available=Math.max(0,info.balance-info.requested);if(v.allocation>available+.005)throw Error(`בחשבון נשארו ${money(available)} שלא הוקצו ליעדים אחרים.`);}savingsProjection({...v,saved:effectiveGoalSavings(next,v)});}
if(kind==='account'){for(const k of ['balance','original','payment','interest'])v[k]=+v[k]||0;if(v.kind==='credit')saveCardFields(next,v,entity);else for(const k of ['billingDay','payFrom','creditLimit','last4','statementsThrough'])delete v[k];if(v.kind!=='deposit')delete v.releaseDate;else{v.releaseDate=String(v.releaseDate||'');if(v.releaseDate&&!validDate(v.releaseDate))throw Error('תאריך השחרור אינו תקין.');}if(v.kind==='debt'&&v.original<v.balance)throw Error('הסכום המקורי צריך להיות לפחות יתרת החוב.');if(entity&&entity.kind!==v.kind&&accountInUse(next,v.id))throw Error('לחשבון יש תנועות, ולכן אין לשנות את סוג החשבון.');if(entity?.kind==='investment'&&v.kind!=='investment'&&containerAssets(next,entity.id).length)throw Error('בחשבון יש נכסים. העבר אותם לחשבון השקעות אחר לפני שינוי הסוג.');
  // 4.1: several investment accounts (containers). The first one created while holdings exist without one gets
  // a "התיק שלי" in front of it for those holdings — unless it is "התיק שלי" itself being named (adopt).
  if(v.kind==='investment'){v.invType=investType(v);v.currency='ILS';v.balance=0;if(!entity&&!investAccounts(next).length&&next.assets.length&&!v.adopt){ensureDefaultContainer(next);message=`נוצר גם ״${DEFAULT_CONTAINER_NAME}״ ל־${next.assets.length} הנכסים שכבר היו בתיק. אפשר לשנות לו שם.`;}}else delete v.invType;delete v.adopt;}
if(kind==='asset'){for(const k of ['quantity','averagePrice','invested','currentPrice','currentValue'])v[k]=+v[k]||0;if(investAccounts(next).length){if(!investAccounts(next).some(a=>a.id===v.accountId))v.accountId=investAccounts(next)[0].id;}else delete v.accountId;if(entity&&(v.currentPrice!==entity.currentPrice||v.currentValue!==entity.currentValue||v.mode!==entity.mode)){delete v.priceDate;delete v.priceSource;}if(!v.invested)v.invested=v.quantity*v.averagePrice;if(v.mode==='price'&&v.quantity>0)v.averagePrice=v.invested/v.quantity;if(v.mode==='price'&&(!v.currentPrice||v.quantity<0))throw Error('יש להזין מחיר חיובי וכמות שאינה שלילית.');const val=assetValue(v),last=sortedSnapshots().at(-1);if(entity&&last&&(v.quantity!==entity.quantity||v.currency!==entity.currency))throw Error('לאחר תחילת המעקב, שינוי כמות יש לרשום כקנייה או מכירה. מטבע של נכס קיים אינו ניתן לשינוי.');if(!entity&&val>0){if(last&&v.date<=last.date)throw Error('נכס חדש צריך להירשם אחרי תאריך תמונת המצב האחרונה.');next.activities.push({id:uid(),type:'opening',date:v.date,amount:val,currency:v.currency,fx:next.fx,assetId:v.id,notes:'יתרה התחלתית של נכס קיים'});}if(ui.monthly){ui.monthly.values[v.id]=v.mode==='price'?v.currentPrice:v.currentValue;ui.monthly.base={...ui.monthly.base,[v.id]:ui.monthly.values[v.id]};}}
if(kind==='activity'){v.amount=+v.amount;v.quantity=+v.quantity;v.fx=+v.fx||next.fx;const last=sortedSnapshots().at(-1);if(!validDate(v.date)||v.date>today()||last&&v.date<=last.date)throw Error('פעולה חדשה צריכה להיות אחרי העדכון האחרון ולא בעתיד.');if(['deposit','withdrawal'].includes(v.type)&&!next.assets.some(a=>a.id===v.assetId&&a.mode==='value'))delete v.assetId;if(v.assetId&&['buy','sell','dividend','distribution','fee','deposit','withdrawal'].includes(v.type))v.currency=next.assets.find(a=>a.id===v.assetId)?.currency||v.currency;applyActivity(next,v);}
if(kind==='category'){v.name=v.name.trim();if(!v.name||next.categories.includes(v.name))throw Error('יש להזין שם קטגוריה חדש.');next.categories.push(v.name);}else if(keys[kind]&&!skip){const arr=next[keys[kind]],index=arr.findIndex(x=>x.id===v.id);if(index>=0)arr[index]=v;else arr.push(v);}const undo=(!!entity&&!!keys[kind])||(kind==='transaction'&&(skip||v.type==='transfer'));commit(next,message||(entity?'השינויים נשמרו':undefined),false,undo?{undo:true}:{});closeDialog();}
function removeEntity(kind,id){const keys={transaction:'transactions',budget:'budgets',goal:'goals',account:'accounts',asset:'assets'},entity=data[keys[kind]].find(a=>a.id===id);if(!entity)return;if(kind==='account'&&entity.kind==='investment')return openContainerRemove(id);if(kind==='account'&&accountInUse(data,id,true)){toast('החשבון מקושר לתנועות, לתשלומים או לכרטיס. אפשר לערוך אותו, אך מחיקה תפגע בהיסטוריה.',true);return;}confirm('למחוק את הפריט?',kind==='asset'?'הנכס יוסר מהתיק הנוכחי ושוויו יירשם כמשיכה היום. תמונות המצב ההיסטוריות יישמרו.':kind==='transaction'?'התנועה תימחק ויתרות החשבונות יתעדכנו.':'הפריט יימחק מהנתונים השמורים. מומלץ להוריד גיבוי קודם.',()=>{const next=structuredClone(data);if(kind==='transaction')applyTransaction(next,entity,-1);if(kind==='asset'&&assetValue(entity)>0){const last=sortedSnapshots().at(-1);if(last&&today()<=last.date)throw Error('אפשר להסיר את הנכס רק לאחר תאריך העדכון האחרון.');next.activities.push({id:uid(),type:'withdrawal',date:today(),amount:assetValue(entity),currency:entity.currency,fx:next.fx,notes:'הסרת נכס: '+entity.name});}if(kind==='account')next.goals=next.goals.map(g=>g.accountId===id?{...g,accountId:'',allocation:null,saved:effectiveGoalSavings(data,entity.kind==='investment'?{...g,accountId:entity.id}:g)}:g);next[keys[kind]]=next[keys[kind]].filter(a=>a.id!==id);commit(next,kind==='transaction'?'התנועה נמחקה':'הפריט נמחק',false,{undo:true});},true);}
function download(filename,value,type='application/json'){const blob=new Blob([value],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportData(format){const list=format.endsWith('filtered')?filteredTransactions():data.transactions;if(format==='backup'){const copy={...data,lastBackup:new Date().toISOString()};download('ofek-backup-'+today()+'.json',JSON.stringify(copy,null,2));commit(copy,'הגיבוי הורד בהצלחה');return;}if(format.startsWith('json')){download('ofek-transactions-'+today()+'.json',JSON.stringify({format:'ofek-transactions',version:1,transactions:list.map(t=>({...t,accountName:data.accounts.find(a=>a.id===t.accountId)?.name,...(t.type==='transfer'?{toAccountName:data.accounts.find(a=>a.id===t.toAccountId)?.name}:{})}))},null,2));toast('התנועות יוצאו ל־JSON');return;}download('ofek-transactions-'+today()+'.csv','\uFEFF'+transactionsCSV(data,list),'text/csv;charset=utf-8');toast('התנועות יוצאו ל־CSV');}
async function importFile(file){try{if(!file)return;if(file.size>10*1024*1024)throw Error('גודל הקובץ המרבי הוא 10MB.');const text=await file.text();let value;if(file.name.toLowerCase().endsWith('.csv'))value={format:'ofek-transactions',transactions:parseTransactionsCSV(data,text)};else value=JSON.parse(text);if(value?.format==="ofek-encrypted"){openDecryptImport(value);return;}if(value.format==='ofek-transactions'){if(!Array.isArray(value.transactions))throw Error('רשימת התנועות אינה תקינה.');const next=structuredClone(data);let count=0,transfers=0;for(const raw of value.transactions){const row=cleanImportedRow(raw);if(next.transactions.some(t=>t.id===row.id))continue;const account=next.accounts.find(a=>a.id===row.accountId||a.name===row.accountName);if(!account)throw Error('לא נמצא חשבון לתנועה '+(row.description||row.category)+'. יש ליצור חשבון בשם '+(row.accountName||row.accountId));const t={...row,id:row.id||uid(),accountId:account.id,fx:row.fx||data.fx};if(!validDate(t.date)||t.date>today()||!(t.amount>0)||!TX_TYPES.includes(t.type)||!['ILS','USD'].includes(t.currency)||!(t.fx>0))throw Error('אחת התנועות מכילה נתונים לא תקינים. לא נשמרו שינויים.');if(t.type==='transfer'||t.type==='refund')t.recurring=false;if(t.type==='transfer'){importTransferRow(next,t,row);transfers++;}else if(!next.categories.includes(t.category))next.categories.push(t.category);applyTransaction(next,t);next.transactions.push(t);count++;}validateData(next);confirm('ייבוא תנועות',`נמצאו ${count} תנועות חדשות${transfers?`, כולל ${transfers} העברות`:''}. התנועות יתווספו והיתרות יתעדכנו. תנועות עם מזהה קיים יידלגו.`,()=>commit(next,`${count} תנועות יובאו בהצלחה`));}else{validateData(value);confirm('שחזור הגיבוי',`הגיבוי כולל ${value.transactions.length} תנועות, ${value.assets.length} נכסים ו־${value.snapshots.length} תמונות מצב. הוא יחליף את הנתונים הנוכחיים. מומלץ להוריד גיבוי קודם.`,()=>{commit(value,'הגיבוי שוחזר בהצלחה',true);ui.monthly=null;ui.monthlyDone=null;});}}catch(err){toast(err.message||'לא הצלחנו לקרוא את הקובץ',true);}}
function clearDemo(){confirm('להסיר את נתוני ההדגמה?','כל הנתונים הנוכחיים, כולל שינויים שנעשו בהדגמה, יימחקו. אפשר להוריד גיבוי לפני ההסרה. האפליקציה תתחיל נקייה כדי להזין את הנתונים שלך.',()=>{commit({...emptyData(),...(data.prefs?{prefs:data.prefs}:{})},'נתוני ההדגמה הוסרו — אפשר להתחיל');ui.month=today().slice(0,7);ui.monthly=null;ui.monthlyDone=null;navigate('dashboard');},true);}
function refreshTransactionResults(){const list=filteredTransactions();document.querySelector('#transaction-results').innerHTML=transactionsTable(list);document.querySelector('#transaction-metrics').innerHTML=transactionMetrics(list);}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const [action,a,b]=button.dataset.action.split(':');try{if(action==='navigate')navigate(a);else if(action==='open')openEntity(a);else if(action==='edit'){const keys={transaction:'transactions',budget:'budgets',goal:'goals',account:'accounts',asset:'assets'};openEntity(a,data[keys[a]].find(v=>v.id===b));}else if(action==='remove')removeEntity(a,b);else if(action==='dialog-close')closeDialog();else if(action==='confirm'){const fn=confirmAction;fn?.();closeDialog();}else if(action==='nav-open'){document.querySelector('.sidebar').classList.add('open');document.querySelector('.sidebar').removeAttribute('inert');document.querySelector('.nav-scrim').hidden=false;button.setAttribute('aria-expanded','true');}else if(action==='nav-close'){document.querySelector('.sidebar').classList.remove('open');if(window.innerWidth<=760)document.querySelector('.sidebar').setAttribute('inert','');document.querySelector('.nav-scrim').hidden=true;}else if(action==='toast-close')document.querySelector('.toast')?.remove();else if(action==='clear-demo')clearDemo();else if(action==='return-help')showDialog('איך מחושבת התשואה?',`<p class="confirm-text">${e(returnHelp)}</p><p class="confirm-text" style="margin-top:18px">XIRR הוא חישוב תשואה שנתית משוקללת תזרימים לפי סכום ותאריך. המעקב מתחיל מתמונת המצב הראשונה, ואינו מנסה לשחזר תשואה מלפני תחילת התיעוד.</p>`);else if(action==='export')exportData(a);else if(action==='import-file')document.querySelector('#import-file').click();else if(action==='toggle-filters'){ui.advanced=!ui.advanced;render();}else if(action==='dash-period'){ui.dashboardPeriod=a;render();}else if(action==='period'){ui.period=a;render();}else if(action==='tx-view'){ui.view=a;ui.filters.day='';if(a==='calendar'){ui.filters.from=ui.calendarMonth+'-01';ui.filters.to=ui.calendarMonth+'-31';}render();}else if(action==='clear-filters'){for(const k in ui.filters)ui.filters[k]='';render();}else if(action==='calendar-prev'||action==='calendar-next'){ui.calendarMonth=monthOffset(ui.calendarMonth,action==='calendar-prev'?-1:1);ui.filters.day='';ui.filters.from=ui.calendarMonth+'-01';ui.filters.to=ui.calendarMonth+'-31';ui.month=ui.calendarMonth;render();}else if(action==='calendar-day'){ui.filters.day=ui.filters.day===a?'':a;render();}else if(action==='calendar-clear'){ui.filters.day='';render();}else if(action==='year-transactions'){ui.filters.from=ui.month.slice(0,4)+'-01-01';ui.filters.to=ui.month.slice(0,4)+'-12-31';ui.filters.day='';ui.view='list';render();}else if(action==='entity-type'){captureEntity();dialogState.v.type=a;entityDialog();}else if(action==='undo')undoLast();else if(action==='transfer-new')openTransfer(a,b);else if(action==='edit-benchmarks')openBenchmarks();else if(action==='edit-target')showDialog('יעד הוצאות חודשי',`<form id="target-form">${field('יעד חודשי (₪)',input('target',data.overallBudget,'number','required min="1"'))}<div class="form-actions">${submit()}${btn('ביטול','dialog-close')}</div></form>`);else if(action==='monthly-add-flow'){captureMonthly();ui.monthly.flows.push({id:uid(),type:'deposit',amount:'',currency:'ILS',fx:ui.monthly.fx,assetId:'',accountId:'',quantity:'',date:ui.monthly.date,notes:''});render();}else if(action==='monthly-remove-flow'){captureMonthly();ui.monthly.flows.splice(+a,1);render();}else if(action==='restore-recovery'){const previous=repository.recovery();if(!previous)throw Error('לא נמצאה שמירה קודמת.');validateData(previous);confirm('שחזור השמירה הקודמת','הנתונים הנוכחיים יוחלפו בשמירה הקודמת של הדפדפן.',()=>commit(previous,'השמירה הקודמת שוחזרה',true));}else if(action==='raw-recovery')download('ofek-recovery-raw.json',localStorage.getItem(STORAGE_KEY+'-unreadable')||localStorage.getItem(STORAGE_KEY)||'{}');else if(action==='reset-all')confirm('למחוק את כל הנתונים?','כל החשבונות, התנועות, ההשקעות ותמונות המצב יימחקו. מומלץ להוריד גיבוי מלא קודם.',()=>{commit(emptyData(),'כל הנתונים הוסרו',true);ui.monthly=null;ui.monthlyDone=null;},true,'מחיקת כל הנתונים');else if(action==='load-demo')confirm('טעינת נתוני הדגמה','נתוני ההדגמה יחליפו את הנתונים הנוכחיים. מומלץ להוריד גיבוי קודם.',()=>{commit(demoData(),'נתוני ההדגמה נטענו',true);ui.month='2026-09';ui.monthly=null;render();});}catch(err){toast(err.message,true);}});
document.addEventListener('input',event=>{const el=event.target;el.setCustomValidity?.('');if(el.closest('#entity-form')&&dialogState?.kind==='goal')updateGoalPreview();if(el.closest('#entity-form')&&dialogState?.kind==='transaction'&&dialogState.v.type==='transfer')updateTransferAmount(el);if(el.closest('#entity-form')&&dialogState?.kind==='transaction'&&dialogState.v.planOn)updatePlanPreview(el);if(el.dataset.filter){ui.filters[el.dataset.filter]=el.value;refreshTransactionResults();}if(el.closest('#monthly-form')){captureMonthly();const preview=document.querySelector('#monthly-estimate');if(preview)preview.innerHTML=monthlyEstimate();}});
document.addEventListener('change',event=>{const el=event.target;try{if(el.dataset.goalAccount!=null&&dialogState?.kind==='goal'){captureEntity();const saved=document.querySelector('#entity-form [name=saved]');const linked=data.accounts.some(a=>a.id===el.value);if(linked){dialogState.v.saved=effectiveGoalSavings(data,dialogState.v);saved.value=dialogState.v.saved;}saved.readOnly=linked;updateGoalPreview();}if(el.id==='import-file'){importFile(el.files[0]);el.value='';return;}if(el.dataset.benchmarkSnapshot!=null){const s=data.snapshots.find(s=>s.id===el.value);if(s){document.querySelector('dialog [name=sp500]').value=s.benchmarks?.sp500??'';document.querySelector('dialog [name=ta125]').value=s.benchmarks?.ta125??'';}}if(el.dataset.change){const [action,key]=el.dataset.change.split(':');if(action==='month'){ui.month=el.value;ui.calendarMonth=el.value;ui.filters.from=el.value+'-01';ui.filters.to=el.value+'-31';ui.filters.day='';}else if(action==='chart-metric')ui.chartMetric=el.value;else if(action==='benchmark')ui[key]=el.checked;else if(action==='performance-from')ui.from=el.value;else if(action==='performance-to')ui.to=el.value;render();}if(el.dataset.entityDynamic){captureEntity();if(dialogState.kind==='transaction'&&(el.name==='accountId'||el.name==='toAccountId'))dialogState.v.toAmount='';if(el.name==='assetId'){const a=data.assets.find(a=>a.id===el.value);if(a)dialogState.v.currency=a.currency;}entityDialog();}if(el.closest('#monthly-form')&&/^flow_\d+_(type|currency|assetId)$/.test(el.name)){captureMonthly();const [,index,key]=el.name.match(/^flow_(\d+)_(.+)$/);if(key==='assetId'){const a=data.assets.find(a=>a.id===el.value);if(a)ui.monthly.flows[+index].currency=a.currency;}render();}}catch(err){toast(err.message,true);}});
document.addEventListener('submit',event=>{event.preventDefault();try{if(event.target.id==='entity-form')saveEntity();else if(event.target.id==='monthly-form')saveMonthly();else if(event.target.id==='settings-form'){const f=new FormData(event.target);commit({...data,profile:String(f.get('profile')||'').trim().slice(0,40)},'ההגדרות נשמרו');}else if(event.target.id==='benchmarks-form'){const f=new FormData(event.target),next=structuredClone(data),s=next.snapshots.find(s=>s.id===f.get('snapshot'));if(!s)throw Error('יש לבחור תמונת מצב.');s.benchmarks={sp500:f.get('sp500')===''?null:+f.get('sp500'),ta125:f.get('ta125')===''?null:+f.get('ta125')};s.benchmarkUpdated=today();commit(next,'מדדי ההשוואה עודכנו');closeDialog();}else if(event.target.id==='target-form'){const f=new FormData(event.target);commit({...data,overallBudget:+f.get('target')},'היעד החודשי נשמר');closeDialog();}}catch(err){const box=document.querySelector('#entity-error');if(box)box.innerHTML=notice(err.message,'error');else toast(err.message,true);}});
document.addEventListener('invalid',event=>event.target.setCustomValidity(event.target.validity.valueMissing?'יש למלא שדה זה.':'יש להזין ערך תקין בטווח המותר.'),true);
function chartTip(event){const point=event.target.closest?.('.graph-point'),chart=point?.closest('.chart');if(!chart)return;const tooltip=chart.querySelector('.chart-hover');tooltip.textContent=point.dataset.tip;tooltip.classList.add('visible');}
document.addEventListener('pointerover',chartTip);document.addEventListener('focusin',chartTip);document.addEventListener('pointerout',event=>{if(event.target.closest?.('.graph-point'))event.target.closest('.chart')?.querySelector('.chart-hover')?.classList.remove('visible');});document.addEventListener('focusout',event=>{if(event.target.closest?.('.graph-point'))event.target.closest('.chart')?.querySelector('.chart-hover')?.classList.remove('visible');});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(pageMeta[page]&&ui.page!==page)navigate(page);});window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY&&event.newValue){try{data=validateData(JSON.parse(event.newValue));render();toast('הנתונים עודכנו מלשונית אחרת');}catch{toast('לא ניתן לקרוא נתונים מלשונית אחרת',true);}}});
